class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 2))
        self.size = [1] * (n + 2)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px != py:
            total = self.size[px] + self.size[py]
            self.parent[px] = py
            self.size[py] = total
            return True
        return False

    def get_full_span_len(self):
        total = self.size[self.find(0)]
        return max(0, total - 1)

