def cnt_odd_bitwise(mask):
    # Count bits that are set (characters with odd frequency in this range)
    return bin(mask).count('1')

MOD = 1000000007

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    result = 1
    for i in range(k):
        result = result * (n - i) // (i + 1)
    return result

def solution(input_str):
