    arr = list(map(int, lines[1].split()))

    p_positions = [i + 1 for i, v in enumerate(arr) if v == -1]
    used_values = set()
    for v in arr:
        if v != -1:
            used_values.add(v)

    available_values = [v for v in range(1, n + 1) if v not in used_values]

    m = len(p_positions)
    m = m  # Should equal len(available_values)

    forbidden_available_count = 0
    for p in p_positions:
        if p in available_values:
            forbidden_available_count += 1

    result = 0
    for k in range(forbidden_available_count + 1):
        if k % 2 == 1:
            term = (combinations(forbidden_available_count, k) * combinations(m - k, m - k)) % MOD
            term = (term * combinations(m, k)) % MOD
            result = (result - term) % MOD
        else:
            term = (combinations(forbidden_available_count, k) * factorial(m - k)) % MOD
            result = (result + term) % MOD

    return str(result % MOD) + '\n'

