# Solution for Lieges of Legendre

def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n = int(first_line[0])
    k = int(first_line[1])

    second_line = lines[1].split()
    a = [int(x) for x in second_line]

    # Compute grundy numbers
    # Pattern for k odd:
    # Cycle length doubles at each power of 2
    # At 2^m <= a < 2^(m+1), there's a pattern

    if k % 2 == 0:
        # When k is even, splitting even pile 2x gives k piles of x
        # Since k is even, XOR sum is 0 (even copies of same value)
        # So from 2x we can go to grundy(2x-1) or 0
        # grundy(a) is just mex{grundy(a-1)} with possible 0
        # This gives: 0,1,0,1,0,1,...
        # Actually, carefully: if we can reach 0, grundy becomes mex{..., 0, grundy(a-1)}

        def grundy_even(x):
            if x == 0:
                return 0
            if x % 2 == 1:
                # odd: can only go to x-1 (even)
                return 1 - (x >> 1 & 1)  # alternates between 0 and 1
            # even: can go to x-1 and 0
            g_prev = grundy_even(x - 1)
            return 0 if g_prev == 1 else 1
    else:
        # When k is odd, splitting even pile 2x gives k piles of x
        # XOR sum is grundy(x) (odd copies)
        # From a: can go to grundy(a-1) or if a even to grundy(a//2)

        # Precompute grundy up to 10^9 (but use pattern)
        # Pattern observation from game theory analysis:
        # For a >= 1:
        # - If a % 2 != 0: grundy[a] = 1
        # - If a % 2 == 0: grundy[a] = grundy[a//2] if (a>>2) % 2 == 1 else 0 (simplified)

        def get_grundy_odd(x):
            if x == 0:
                return 0
            if x % 2 == 1:
                return 1 - (x >> 1 & 1)  # pattern: 1,0,1,0,1,0...

            # For even numbers, we need to compute recursively
            # Let's observe pattern more carefully
            x >>= 1  # x = a/2
            if x % 2 == 1:
                return 1
            # Keep dividing by 2 until we hit odd
            while x % 2 == 0 and x > 0:
                x >>= 1
                x -= 1
                x //= 2
            if x % 2 == 0:
                return 0
            return 1

    # Better approach: compute grundy with memoization using the correct recurrence
    memo = {0: 0}

    def compute_grundy(a):
        if a in memo:
            return memo[a]
        if a % 2 == 1:
            # odd: can only go to a-1 (even)
            g = 1 - memo[a - 1]  # grundy(a-1) is either 0 or 1
            memo[a] = g
            return g
        else:
            # even: can go to a-1 or grundy(a//2)
            options = {compute_grundy(a - 1)}
            if k % 2 == 1:
                options.add(memo[a // 2] if (a // 2) in memo else compute_grundy(a // 2))
            for idx in options:
                memo[a] = mex(idx, memo)
                break

    def mex(base, memo_):
        result = 0
        while result in base or result in memo_.get(1, set()):
            result += 1
        return result

    # Actually, use direct formula pattern for k odd
