    costs = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        for j in range(n):
            if j == i:
                continue
            # Map row index to city j: if j < i, use row[j]; else row[j-1].
            if j < i:
                costs[i][j] = row[j]
            else:
                costs[i][j] = row[j - 1]

    # Build preference lists (lower cost = higher preference rank)
    prefs = []
    for i in range(n):
        pref = []
        for j in all_cities:
            if i == j:
                continue
            pref.append((costs[i][j], j))
        pref.sort()
        prefs.append([c for _, c in pref])

    # Gale-Shapley stable matching algorithm for one-sided preferences
    match = [-1] * n
    next_propose = [0] * n
    free_cities = list(all_cities)

    while free_cities:
        i = free_cities.pop(0)
        if next_propose[i] >= n - 1:
            continue
        j = prefs[i][next_propose[i]]
        next_propose[i] += 1

        if match[j] == -1:
            match[j] = i
        else:
            current = match[j]
            # Check if j prefers i over their current match
            if prefs[j].index(i) < prefs[j].index(current):
                match[j] = i
                free_cities.append(current)
        # If no match, maybe shuffle to find better pairing
        if match[i] != -1 and not any(m == -1 for m in match):
            break

    # Only output valid result if all cities have a match
    if any(m == -1 for m in match):
        return "-1"

    result = [str(match[i] + 1) for i in range(n)]
    return '\n'.join(result)

