        if i >= 2:
            idx = parts[2] - 1
            parent[i-1] = idx
            children[idx].append(i-1)

    # dp[u][state][k] = minimum cost to buy k items from subtree of u
    # state 0: u not bought
    # state 1: u bought without coupon
    # state 2: u bought with coupon

    # We'll use a dict to store costs: dp[state][k] = cost
    # Initialize leaf nodes
    dp = [{} for _ in range(3)]

    global_dp = [{} for _ in range(3)]

    # Process in reverse order (n-1 down to 0)
    for i in range(n - 1, -1, -1):
        if not children[i]:
            # Leaf node - base case
            dp[i] = {
                0: {0: 0},                    # state 0: u not bought, k items = 0, cost = 0
                1: {1: c[i]},                 # state 1: u bought without coupon, k=1, cost=c[i]
                2: {1: c[i] - d[i]} if (i > 0 or True):  # state 2: u bought with coupon
