                2: {1: c[i] - d[i]}           # state 2: u bought with coupon
            }

            # Merge each child
            for child in children[i]:
                new_dp = [[{} for _ in range(3)] for __ in range(n + 1)]

                for state_u in range(3):
                    for state_v in range(3):
                        # Check if valid transitions
