                            continue  # Can't use coupon on u if child doesn't use coupon when needed

                        for k_u in dp[state_u]:
                            for k_v in dp[state_v]:
                                k_total = k_u + k_v
                                cost_total = dp[state_u][k_u] + dp[state_v][k_v]

                                if k_total not in new_dp[state_u]:
                                    new_dp[state_u][k_total] = cost_total
                                else:
                                    new_dp[state_u][k_total] = min(new_dp[state_u][k_total], cost_total)

                dp[i] = new_dp

        # Update next level (parent processing)
        if children[i]:
            parent_idx = parent[i]
            for child in children[i]:
