def solution(input_str):
    n, l, r = map(int, input_str.split())

    if n == 1:
        return str(r - l + 1)

    if n == 2:
        cnt = r - l + 1
        return str(cnt * (cnt - 1))

    # For n >= 3, count increasing sequences (d > 1) then decreasing (d < 1)
    count = 0

    # Helper to count sequences with ratio d = p/q > 1
    def count_increasing(p, q, n, l, r):
        q_pow = q ** (n - 1)
        p_pow = p ** (n - 1)

        if q_pow > r:
            return 0

        # Minimum valid a1: ceil(l * p_pow / q_pow), divisible by q_pow
        min_a1_raw = l * p_pow
        if min_a1_raw % q_pow == 0:
            min_a1 = min_a1_raw // q_pow
        else:
            min_a1 = (min_a1_raw // q_pow) + 1

        # Only valid if min_a1 is actually >= q_pow * ceil(min_a1/q_pow)
        # i.e., a1 must be multiple of q_pow and >= l
        if min_a1 % q_pow != 0:
            min_a1 += q_pow - (min_a1 % q_pow)

        if min_a1 > r or min_a1 < l:
            return 0

        # Maximum a1: floor(r * q_pow / p_pow)
        max_a1_raw = r * q_pow
        if max_a1_raw % p_pow == 0:
            max_a1 = max_a1_raw // p_pow
        else:
            max_a1 = (max_a1_raw // p_pow)

        if max_a1 < min_a1:
            return 0

        # Count multiples of q_pow in [min_a1, max_a1]
        first_valid = ((_ = (min_a1 + q_pow - 1) // q_pow) * q_pow)
        last_valid = (max_a1 // q_pow) * q_pow
        if first_valid > last_valid:
            return 0
        return (last_valid // q_pow) - ((first_valid // q_pow) - 1)

    # Iterating against yaza > 1, d = p/q
    # Determine max denominator q: q^(n-1) * p^(n-1) <= r
    max_q = int(r ** (1.0 / (n - 1)) * 2.0) + 2

    for q in range(2, max_q + 1):
        q_pow = q ** (n - 1)
        if q_pow > r:
            break

        for p in range(q + 1, min(q * 2 + 1, max_q * n + 1)):
            if p > q and gcd(p, q) != 1:
                continue
            if p ** (n - 1) > r:
                break

            cnt = count_increasing(p, q, n, l, r)
            if cnt > 0:
                count += cnt

    # Decreasing sequences (d < 1) correspond to reversed increasing sequences
    # Example: if (4,6,9) increasing has d=3/2, then (9,6,4) decreasing has d=2/3
    # These are both valid distinct sequences
    # Count sequences corresponding to d = p/q where we're counting decreasing
    # d < 1 means p < q. The viewpoint is reversed: we count when d' = q/p > 1
    for q in range(2, max_q + 1):
        q_pow = q ** (n - 1)
        if q_pow > r:
            break

        for p in range(1, q):
            q_p = gcd(p, q)
            if q_p != 1:
                continue

            p_pow = p ** (n - 1)
            if p_pow > r:
                continue

            # For decreasing: a1 corresponds to first term
            # a1 >= l with l * q^(n-1) / p^(n-1) >= min_a1
            # a1 <= r

            min_a1_raw = l * q_pow
            if min_a1_raw % p_pow == 0:
                min_a1 = min_a1_raw // p_pow
            else:
                min_a1 = (min_a1_raw // p_pow) + 1

            if min_a1 > r:
                continue

            # a1 must be multiple of q_pow
            if min_a1 % q_pow == 0:
                first = min_a1
            else:
                first = min_a1 + (q_pow - min_a1 % q_pow) % q_pow

            last = (r // q_pow) * q_pow
            if first > last:
                continue

            cnt = (last // q_pow) - ((first // q_pow) - 1)
            if cnt > 0:
                count += cnt

    return str(count)

