    def query(r, c):
        queries.append(f"? {r} {c}")
        return matrix[r-1][c-1]

    def find_min(r1, r2, c1, c2):
        """
        Find minimum in rows r1..r2 and columns c1..c2.
        Returns (min_value, row_index, col_index)
        """
        if r1 > r2 or c1 > c2:
            return (float('inf'), 0, 0)
        if r1 == r2 and c1 == c2:
            return (query(r1, c1), r1, c1)
        if r1 == r2:
            # Single row - find minimum in column range
            min_val, min_col = query(r1, c1), c1
            for c in range(c1 + 1, c2 + 1):
                val = query(r1, c)
                if val < min_val:
                    min_val, min_col = val, c
            return (min_val, r1, min_col)

        mid = (r1 + r2) // 2

        # First find minimum in top half
        val1, row1, col1 = find_min(r1, mid, c1, c2)

        # If no valid result from top half (shouldn't happen normally), return bottom
        if val1 > 2 * 10**9:
            val2, row2, col2 = find_min(mid + 1, r2, c1, c2)
            return (val2, row2, col2)

        # Search bottom half starting from col1 (minimum column index is non-decreasing in rows)
        val2, row2, col2 = find_min(mid + 1, r2, col1, c2)

        # Return the minimum value found
        if val1 <= val2:
            return (val1, row1, col1)
        return (val2, row2, col2)

    min_val, _, _ = find_min(1, n, 1, m)
    queries.append(f"! {min_val}")
    return '\n'.join(queries)

