    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = map(int, parts[:2])
            adj[u].append(v)

    ids = [0] * (n + 1)
    low = [0] * (n + 1)
    scc = [0] * (n + 1)
    on_stack = [False] * (n + 1)
    stack = []
    id_counter = 0
    scc_count = 0

    def dfs(u):
        nonlocal id_counter
        id_counter += 1
        ids[u] = low[u] = id_counter
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if ids[v] == 0:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            while stack:
                w = stack.pop()
                on_stack[w] = False
                scc[w] = scc_count
                if w == u:
                    break
            scc_count += 1

    for i in range(1, n + 1):
        if ids[i] == 0:
            dfs(i)

    # Calculate SCC sizes
    scc_size = [0] * scc_count
    for v in range(1, n + 1):
        scc_size[scc[v]] += 1

    # Count vertices in non-trivial SCCs (|SCC| > 1)
    k = 0
    for v in range(1, n + 1):
        if scc_size[scc[v]] > 1:
            k += 1
        else:
            k += 1  # All vertices count

    # Count vertices in cycles (non-trivial SCCs)
    vertices_in_cycles = 0
    for v in range(1, n + 1):
        if scc_size[scc[v]] > 1:
            vertices_in_cycles += 1

    # Formula: 999 per vertex in non-trivial SCC + 1 per acyclic vertex + 1
    total = 0
    for v in range(1, n + 1):
        if scc_size[scc[v]] > 1:
            total += 999
        else:
            total += 1

    return str(total + 1)

from itertools import combinations_with_replacement

def solution(input_str):
    n, r = map(int, input_str.split())

    # Generate all valid integer points within distance r
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))

    def get_score(positions):
        """Calculate sum of squared distances between all pairs of towers"""
        total = 0
        m = len(positions)
        for i in range(m):
            for j in range(i + 1, m):
                dx = positions[i][0] - positions[j][0]
                dy = positions[i][1] - positions[j][1]
                total += dx * dx + dy * dy
        return total

    best_score = -1
    best_config = None

    # Build list of points sorted by squared distance from origin (descending)
    points_by_dist_sq = sorted(points, key=lambda p: p[0]**2 + p[1]**2, reverse=True)

    # Search for optimal configuration
    # Try using only the k most distant points
    for limit in range(1, min(len(points_by_dist_sq) + 1, 21)):
        candidates = points_by_dist_sq[:limit]

        # Try all combinations with replacement
        if len(candidates) <= 8:
            for positions in combinations_with_replacement(candidates, n):
                score = get_score(positions)
                if score > best_score:
                    best_score = score
                    best_config = positions

        if len(candidates) <= 20:
            # Also try combinations with fewer distinct points for efficiency
            for num_distinct in range(1, min(len(candidates) + 1, n + 1)):
                for positions in combinations_with_replacement(candidates, num_distinct)[:50]:
                    # Pad until we have n towers
                    if len(positions) < n:
                        continue

                    score = get_score(positions[:n])
                    if score > best_score:
                        best_score = score
                        best_config = positions[:n]

    # If no configuration found, use the best single point repeated
    if best_config is None:
        best_config = (points_by_dist_sq[0],) * n
        best_score = get_score(best_config)

    # Format output
    lines = [str(best_score)]
    for p in best_config:
        lines.append(f"{p[0]} {p[1]}")
    return '\n'.join(lines)


