    prime = [True] * (int(n**0.5) + 2)
    primes = []
    for i in range(2, len(prime)):
        if prime[i]:
            primes.append(i)
            for j in range(i*i, len(prime), i):
                prime[j] = False

    result = 0
    temp = n
    for p in primes:
        if p * p > temp:
            break
        if temp % p == 0:
            count = 0
            while temp % p == 0:
                count += 2
                temp //= p
        if count == 2:
            result = (result * p) % (2 * 10**9 + 7)

    if temp > 1:
        result = (result * temp) % (2 * 10**9 + 7)

    return result

