    n, m = map(int, lines[0].split())

    roads = []
    for line in lines[1:]:
        line = line.strip()
        if line:
            parts = list(map(int, line.split()))
            roads.append((parts[0], parts[1]))

    # Normalize each road: ensure a < b
    roads = [tuple(sorted(r)) for r in roads]

    def cross(r1, r2):
        """Check if two chords cross (interleave their endpoints)"""
        a1, b1 = r1
        a2, b2 = r2

        # Two chords cross if their endpoints alternate around the ring
        # a1 < a2 < b1 < b2 or a2 < a1 < b2 < b1
        return (a1 < a2 < b1 < b2) or (a2 < a1 < b2 < b1)

    # Build conflict graph: nodes are roads, edges represent intersecting roads
    conflict = [[] for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if cross(roads[i], roads[j]):
                conflict[i].append(j)
                conflict[j].append(i)

    # Try to 2-color the graph (0 = inside, 1 = outside)
    color = [-1] * m

    def dfs(u, c):
        color[u] = c
        for v in conflict[u]:
            if color[v] == -1:
                if not dfs(v, 1 - c):
                    return False
            elif color[v] == c:
                return False
        return True

    possible = True
    for i in range(m):
        if color[i] == -1:
            if not dfs(i, 0):
                possible = False
                break

    if not possible:
        return "Impossible\n"

    # Build result string
    result = []
    for i in range(m):
        result.append('i' if color[i] == 0 else 'o')

    return ''.join(result) + '\n'


