        # g(2^m - 1) = accumulated sequence
        # g(k) follows pattern based on bit structure

        # Build answer from lower bits to higher bits
        def compute_g(n):
            if n == 0:
                return 1
            if n == 1:
                return 2
            if n == 2:
                return 3
            if n == 3:
                return 5
            if n == 4:
                return 6
            if n == 7:
                return 14

            g = [0] * (n + 1)
            g[0] = 1
            for i in range(1, n + 1):
                msb = i.bit_length() - 1
                if msb == 0:
                    g[i] = g[i - 1] + 1
                else:
                    g[i] = g[i - (1 << msb)] + (1 << msb)
            return g[n]

        ans = (ans + compute_g(m)) % MOD

    return str(ans % MOD) + "\n"


if __name__ == "__main__":
    print(solution("1\n"))  # Expected: 2
    print(solution("2\n"))  # Expected: 3  
    print(solution("3\n"))  # Expected: 5
    print(solution("4\n"))  # Expected: 6

from collections import deque

def solution(s):
    n = int(s.strip())

    if n == 0:
        return "0\n"

    # BFS to find minimum operations
    # visited stores (number -> steps to reach it)
    visited = {n: 0}
    queue = deque([(n, 0)])

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps) + "\n"

        # Get all unique digits in the current number
        digits = set(str(current))

        for d in digits:
            if d != '0':  # Can't subtract 0 as it wouldn't change the number
                next_val = current - int(d)
                if next_val not in visited:
                    visited[next_val] = steps + 1
                    queue.append((next_val, steps + 1))

    # Fallback (shouldn't reach here for normal inputs)
    return "0\n"

if __name__ == "__main__":
    import sys
    for line in sys.stdin:
        print(solution(line))

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        s = parts[0]
        c = int(parts[1])
        attempts.append((s, c))

    count = 0

    # Try all 2^n possible codes
    for mask in range(1 << n):
        code = []
        for j in range(n):
            # Bit j=0 is the first character (MSB), j=n-1 is the last character (LSB)
            bit = (mask >> (n - 1 - j)) & 1
            code.append('1' if bit else '0')

        code_str = ''.join(code)

        # Check if this code satisfies all m constraints
        valid = True
        for s, c in attempts:
            matches = 0
            for i in range(n):
                if code_str[i] == s[i]:
                    matches += 1
            if matches != c:
                valid = False
                break

        if valid:
            count += 1

    return str(count)


