def solution(n_str):
    n = int(n_str.strip())

    # If N is 0, no triples possible
    if n == 0:
        return "0\n"

    # Count numbers in [1,n] with each digital root
    # digital root: x % 9 if x % 9 != 0 else 9
    dr_count = [0] * 10
    for i in range(1, n + 1):
        r = i % 9
        dr_count[r or 9] += 1

    # Count all triples (A, B, C) where d(AB) = d(C)
    # Since d(AB) = d(d(A) * d(B)), we work with digital roots
    total = 0
    for ra in range(1, 10):
        for rb in range(1, 10):
            # Digital root of product of two numbers
            pr = (ra * rb) % 9
            dr = pr or 9

            # Number of pairs (A,B) with digital roots ra, rb
            if dr_count[ra] and dr_count[rb]:
                count_pairs = dr_count[ra] * dr_count[rb]

                # Number of C with same digital root as product
                total += count_pairs * dr_count[dr]

    # Subtract cases where AB = C (algorithm is correct for these)
    # Count divisor pairs (a, b) where a*b = c and a,b <= n for each c in [1,n]
    subtract = 0
    for c in range(1, n + 1):
        a = 1
        while a * a <= c:
            if c % a == 0:
                b = c // a
                if a <= n and b <= n:
                    if a == b:
                        subtract += 1
                    else:
                        subtract += 2
            a += 1

    return str(total - subtract) + '\n'
